"""Fiches prototype — filiere generale, Histoire-Geographie et EMC (partie E).

14 fiches : 11 Histoire-Geographie (HG1..HG11) + 3 EMC (EM1..EM3).
Format strict FICHE_UV : 12 points, 10 questions (8 QCM + 2 texte), 7 blocs,
3 schemas SVG. Sources : programmes officiels, BO et eduscol.
"""
import os
import sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
